{
  "name": "ssg",
  "version": "1.0.0",
  "description": "A static site generator CLI built with TypeScript",
  "license": "MIT",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "ssg": "dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "prepare": "npm run build",
    "test": "jest",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "gray-matter": "^4.0.3",
    "marked": "^12.0.2"
  },
  "devDependencies": {
    "@types/jest": "^29.5.12",
    "@types/node": "^20.12.7",
    "jest": "^29.7.0",
    "ts-jest": "^29.1.2",
    "typescript": "^5.4.5"
  }
}

/** @type {import('ts-jest').JestConfigWithTsJest} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/src'],
  testMatch: ['**/__tests__/**/*.test.ts', '**/?(*.)+(spec|test).ts'],
  moduleFileExtensions: ['ts', 'js', 'json'],
  transform: {
    '^.+\\.ts$': ['ts-jest', { tsconfig: 'tsconfig.json' }],
  },
  collectCoverageFrom: ['src/**/*.ts', '!src/**/*.test.ts', '!src/cli.ts'],
};

/**
 * Shared types for the static site generator.
 */

/** Parsed metadata for a Markdown page. */
export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

/** A fully processed page ready to be rendered. */
export interface Page {
  /** Slug derived from the source file name (without extension). */
  slug: string;
  /** Absolute or relative path of the source Markdown file. */
  sourcePath: string;
  /** The HTML file name this page will be written to. */
  outputName: string;
  /** Page title (frontmatter title, falling back to the slug). */
  title: string;
  /** Publication date, if provided. */
  date?: string;
  /** List of tags, if provided. */
  tags: string[];
  /** Rendered HTML body of the page. */
  html: string;
  /** Raw Markdown body (frontmatter stripped). */
  content: string;
  /** Raw source file contents. */
  raw: string;
  /** Full parsed frontmatter data. */
  data: Frontmatter;
}

/** Options controlling how a site is built. */
export interface BuildOptions {
  /** Directory containing Markdown content files. */
  contentDir: string;
  /** Directory where generated HTML files are written. */
  outputDir: string;
}

/**
 * Frontmatter parsing.
 *
 * gray-matter only parses JSON frontmatter out of the box, so the
 * `---`-delimited YAML block is parsed here with a simple key: value
 * splitter and merged into gray-matter's output before the data is
 * passed on to the renderer.
 */

import matter from 'gray-matter';
import type { Frontmatter } from './types';

const DELIMITER_RE = /^---[ \t]*\r?\n([\s\S]*?)\r?\n[ \t]*---[ \t]*(?:\r?\n|$)/;

/**
 * Extract the raw YAML block (the text between the leading `---`
 * delimiters) from a Markdown source string, or null if there is no
 * frontmatter block.
 */
export function extractYamlBlock(source: string): string | null {
  const match = DELIMITER_RE.exec(source);
  return match ? match[1] : null;
}

/**
 * Coerce a single scalar string into a more useful typed value.
 * Handles quoted strings, numbers, booleans, inline arrays and
 * comma-separated lists (e.g. `tags: a, b`).
 */
export function coerceScalar(value: string): unknown {
  const trimmed = value.trim();

  // Inline array: [a, b, c]
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    return trimmed
      .slice(1, -1)
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)
      .map((item) => stripQuotes(item));
  }

  // Strip surrounding single or double quotes
  const unquoted = stripQuotes(trimmed);

  if (unquoted === 'true') return true;
  if (unquoted === 'false') return false;
  if (/^-?\d+(\.\d+)?$/.test(unquoted)) return Number(unquoted);

  // Comma-separated list such as `tags: foo, bar`
  if (unquoted.includes(',')) {
    return unquoted.split(',').map((item) => item.trim()).filter(Boolean);
  }

  return unquoted;
}

function stripQuotes(value: string): string {
  if (value.length >= 2) {
    const first = value[0];
    const last = value[value.length - 1];
    if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
      return value.slice(1, -1);
    }
  }
  return value;
}

/**
 * Parse a `---`-delimited YAML block into a plain object using a simple
 * `key: value` splitter. Supports:
 *  - scalar values: `key: value`
 *  - quoted values: `key: "value"`, `key: 'value'`
 *  - inline arrays: `tags: [a, b]`
 *  - comma separated lists: `tags: a, b`
 *  - block lists:  `tags:\n  - a\n  - b`
 */
export function parseYamlBlock(block: string): Record<string, unknown> {
  const data: Record<string, unknown> = {};

  let listKey: string | null = null;
  const listItems: string[] = [];

  for (const rawLine of block.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const listMatch = line.match(/^-\s+(.*)$/);
    if (listMatch) {
      if (listKey) {
        listItems.push(stripQuotes(listMatch[1].trim()));
      }
      continue;
    }

    const separatorIndex = line.indexOf(':');
    if (separatorIndex === -1) continue;

    const key = line.slice(0, separatorIndex).trim();
    if (!key) continue;

    const rawValue = line.slice(separatorIndex + 1).trim();

    // If a previous list was being accumulated, finalize it first.
    if (listKey && listItems.length > 0) {
      data[listKey] = [...listItems];
    }
    listKey = null;
    listItems.length = 0;

    if (rawValue === '') {
      // Empty value: might be the header of a block list on the next lines.
      listKey = key;
      continue;
    }

    data[key] = coerceScalar(rawValue);
  }

  if (listKey && listItems.length > 0) {
    data[listKey] = [...listItems];
  }

  return data;
}

/**
 * Parse a Markdown source string into frontmatter data and body content.
 * gray-matter handles the delimiter + content splitting (and JSON
 * frontmatter), and the custom YAML parser output is merged on top so
 * that YAML frontmatter is fully supported.
 */
export function parseFrontmatter(source: string): {
  data: Frontmatter;
  content: string;
} {
  const parsed = matter(source);

  const block = extractYamlBlock(source);
  const yamlData = block ? parseYamlBlock(block) : {};

  const gmData = (parsed.data ?? {}) as Record<string, unknown>;
  const data: Record<string, unknown> = { ...gmData, ...yamlData };

  // Normalise tags into a string array regardless of the source format.
  if ('tags' in data) {
    data.tags = normalizeTags(data.tags);
  }

  return { data: data as Frontmatter, content: parsed.content };
}

/** Normalise a tags value (array, comma list, block list) into string[]. */
export function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags.split(',').map((tag) => tag.trim()).filter(Boolean);
  }
  return [];
}

/**
 * Markdown → HTML rendering using `marked`.
 */

import { marked } from 'marked';

/**
 * Render a Markdown string to HTML using GitHub-flavoured Markdown.
 */
export function markdownToHtml(markdown: string): string {
  const result = marked.parse(markdown, {
    gfm: true,
    breaks: true,
  });
  return typeof result === 'string' ? result : markdown;
}

/**
 * HTML templates for individual pages and the site index.
 */

import type { Frontmatter, Page } from './types';

/** Escape HTML-sensitive characters in a string. */
export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Build the `<title>` value for a page. */
export function pageTitle(data: Frontmatter, fallback: string): string {
  return typeof data.title === 'string' && data.title.trim() ? data.title : fallback;
}

/** Render a single page into a complete HTML document. */
export function renderPage(page: Page): string {
  const title = escapeHtml(page.title);

  const meta: string[] = [];
  if (page.date) {
    meta.push(`<p class="date">${escapeHtml(page.date)}</p>`);
  }
  if (page.tags.length > 0) {
    const tags = page.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
    meta.push(`<p class="tags">${tags}</p>`);
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
</head>
<body>
  <header>
    <h1>${title}</h1>
    ${meta.join('\n    ')}
  </header>
  <main>
${page.html}
  </main>
  <footer>
    <p><a href="index.html">&laquo; Back to index</a></p>
  </footer>
</body>
</html>
`;
}

/** Render the site index listing every page. */
export function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const title = escapeHtml(page.title);
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      const tags = page.tags.length
        ? ` <span class="tags">${page.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</span>`
        : '';
      return `    <li><a href="${escapeHtml(page.outputName)}">${title}</a>${date}${tags}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Index</title>
</head>
<body>
  <header>
    <h1>Site Index</h1>
  </header>
  <main>
    <ul>
${items || '    <li>No pages yet.</li>'}
    </ul>
  </main>
</body>
</html>
`;
}

/**
 * Site building logic: reads Markdown files from the content directory,
 * renders each into its own HTML file, and generates an index.html.
 */

import fs from 'fs';
import path from 'path';

import { parseFrontmatter } from './frontmatter';
import { markdownToHtml } from './markdown';
import { pageTitle, renderIndex, renderPage } from './render';
import type { BuildOptions, Frontmatter, Page } from './types';

/** Strip the file extension to produce a page slug. */
export function slugify(filename: string): string {
  return filename.replace(/\.[^.]+$/, '');
}

function ensureDirectoryExists(dir: string): void {
  fs.mkdirSync(dir, { recursive: true });
}

/** List Markdown files (non-recursive) inside the content directory. */
export function listMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) return [];
  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && /\.md$/i.test(entry.name))
    .map((entry) => entry.name)
    .sort();
}

/** Read and parse a single Markdown file into a Page object. */
export function readPage(fileName: string, contentDir: string): Page {
  const sourcePath = path.join(contentDir, fileName);
  const raw = fs.readFileSync(sourcePath, 'utf8');
  const { data, content } = parseFrontmatter(raw);

  const slug = slugify(fileName);
  const title = pageTitle(data, slug);

  return {
    slug,
    sourcePath,
    outputName: `${slug}.html`,
    title,
    date: data.date,
    tags: normalizePageTags(data),
    html: markdownToHtml(content),
    content,
    raw,
    data,
  };
}

function normalizePageTags(data: Frontmatter): string[] {
  const tags = data.tags;
  if (Array.isArray(tags)) return tags.map(String).filter(Boolean);
  if (typeof tags === 'string') return tags.split(',').map((t) => t.trim()).filter(Boolean);
  return [];
}

/** Load and parse every Markdown file in the content directory. */
export function loadPages(contentDir: string): Page[] {
  return listMarkdownFiles(contentDir).map((fileName) => readPage(fileName, contentDir));
}

/**
 * Build the site: render every page into its own HTML file inside the
 * output directory, then generate index.html. Returns the built pages.
 */
export function buildSite(options: BuildOptions): Page[] {
  const { contentDir, outputDir } = options;
  ensureDirectoryExists(outputDir);

  const pages = loadPages(contentDir);

  for (const page of pages) {
    const outputPath = path.join(outputDir, page.outputName);
    fs.writeFileSync(outputPath, renderPage(page));
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages));

  return pages;
}

/**
 * Static site generator CLI.
 *
 *   npx ssg build [--content <dir>] [--output <dir>]
 */

import path from 'path';

import { buildSite } from './site';

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';

export const USAGE = `Usage: ssg build [options]

Options:
  --content <dir>   Directory containing Markdown files (default: ${DEFAULT_CONTENT_DIR})
  --output <dir>    Directory where the site is written (default: ${DEFAULT_OUTPUT_DIR})
  -h, --help        Show this help message`;

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
  help: boolean;
}

/** Parse raw CLI arguments (excluding node and the script path). */
export function parseArgs(argv: string[]): CliOptions {
  let command = '';
  let contentDir = path.resolve(DEFAULT_CONTENT_DIR);
  let outputDir = path.resolve(DEFAULT_OUTPUT_DIR);
  let help = false;

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];

    if (arg === 'build') {
      command = 'build';
    } else if (arg === '--content' || arg === '-c') {
      const value = argv[i + 1];
      if (value && !value.startsWith('--')) {
        contentDir = path.resolve(value);
        i += 1;
      }
    } else if (arg === '--output' || arg === '-o') {
      const value = argv[i + 1];
      if (value && !value.startsWith('--')) {
        outputDir = path.resolve(value);
        i += 1;
      }
    } else if (arg === '--help' || arg === '-h') {
      help = true;
    }
  }

  return { command, contentDir, outputDir, help };
}

/**
 * Run the CLI. Returns the process exit code.
 * The exported signature accepts the raw process.argv so it can be
 * driven from tests.
 */
export function main(argv: string[]): number {
  const options = parseArgs(argv.slice(2));

  if (options.help) {
    console.log(USAGE);
    return 0;
  }

  if (options.command !== 'build') {
    console.error(USAGE);
    return 1;
  }

  const pages = buildSite({
    contentDir: options.contentDir,
    outputDir: options.outputDir,
  });

  console.log(
    `Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${options.outputDir}`
  );
  return 0;
}

// Allow the module to be imported (e.g. by tests) without executing.
if (require.main === module) {
  process.exitCode = main(process.argv);
}

/**
 * Public API surface for the static site generator.
 */

export * from './types';
export { parseFrontmatter, parseYamlBlock, extractYamlBlock, coerceScalar, normalizeTags } from './frontmatter';
export { markdownToHtml } from './markdown';
export { escapeHtml, pageTitle, renderIndex, renderPage } from './render';
export { buildSite, loadPages, listMarkdownFiles, readPage, slugify } from './site';

import { extractYamlBlock, normalizeTags, parseFrontmatter, parseYamlBlock } from '../frontmatter';

describe('parseYamlBlock', () => {
  it('parses scalar key/value pairs', () => {
    const data = parseYamlBlock('title: Hello\ndate: 2026-01-15');
    expect(data.title).toBe('Hello');
    expect(data.date).toBe('2026-01-15');
  });

  it('parses quoted values and strips surrounding quotes', () => {
    const data = parseYamlBlock('title: "Hello World"\nauthor: \'Jane\'');
    expect(data.title).toBe('Hello World');
    expect(data.author).toBe('Jane');
  });

  it('parses numbers and booleans', () => {
    const data = parseYamlBlock('count: 42\nrating: 4.5\npublished: true\nhidden: false');
    expect(data.count).toBe(42);
    expect(data.rating).toBe(4.5);
    expect(data.published).toBe(true);
    expect(data.hidden).toBe(false);
  });

  it('parses inline arrays', () => {
    const data = parseYamlBlock('tags: [a, b, c]');
    expect(data.tags).toEqual(['a', 'b', 'c']);
  });

  it('parses comma separated lists', () => {
    const data = parseYamlBlock('tags: one, two, three');
    expect(data.tags).toEqual(['one', 'two', 'three']);
  });

  it('parses YAML block lists', () => {
    const data = parseYamlBlock('tags:\n  - a\n  - b\n  - c');
    expect(data.tags).toEqual(['a', 'b', 'c']);
  });

  it('skips comments and blank lines', () => {
    const data = parseYamlBlock('# a comment\ntitle: X\n\n\nauthor: Y');
    expect(data.title).toBe('X');
    expect(data.author).toBe('Y');
